import boto3
from datetime import datetime, timedelta

def check_cloudtrail_activity(self, role_name, hours=24):
    """Check CloudTrail for API calls made by the compromised role"""
    start_time = datetime.utcnow() - timedelta(hours=hours)

    events = self.cloudtrail.lookup_events(
        LookupAttributes=[{
            'AttributeKey': 'RoleName',
            'AttributeValue': role_name
        }],
        StartTime=start_time
    )

    suspicious_events = []
    high_risk_actions = [
        'iam:CreateUser', 'iam:CreateAccessKey', 'iam:AttachUserPolicy',
        's3:GetObject', 'rds:DescribeDBInstances',
        'ec2:RunInstances', 'sts:AssumeRole'
    ]

    for event in events['Events']:
        if any(action in event.get('EventName', '') for action in [a.split(':')[1] for a in high_risk_actions]):
            suspicious_events.append({
                'time': event['EventTime'],
                'action': event['EventName'],
                'source_ip': event.get('SourceIpAddress', 'unknown')
            })

    return suspicious_events
